// Pre-publication quality gate. Blocking errors stop publishing; warnings are shown to the reviewer.
const cfg = $('Config').first().json;
const agent = $input.first().json;
const blocking = [];
const warnings = [];

let posts = agent.output;
if (!Array.isArray(posts)) {
  blocking.push('Agent output is not a list of posts');
  posts = [];
}

const byPlatform = {};
for (const p of posts) byPlatform[String((p && p.platform) || '').toLowerCase()] = p;

const REQUIRED = ['linkedin', 'twitter', 'threads', 'reddit'];
const LIMITS = {
  twitter: Number(cfg.x_max_chars),
  threads: Number(cfg.threads_max_chars),
  linkedin: Number(cfg.linkedin_max_chars),
};
const normUrl = (u) => String(u).replace(/[.,;:!?)]+$/, '').replace(/\/+$/, '');
const allowed = normUrl(cfg.workflow_url || '');
const URL_RE = /https?:\/\/[^\s)\]>"']+/g;
const CLAIM_RE = /\b\d+(?:[.,]\d+)?\s?(?:%|x|×|k|m|hours?|minutes?|days?|times)\b/gi;

for (const key of REQUIRED) {
  const p = byPlatform[key];
  if (!p) { blocking.push(`Missing post for platform: ${key}`); continue; }

  const text = String(p.content || '').trim();
  if (!text) { blocking.push(`${key}: empty content`); continue; }

  if (LIMITS[key] && text.length > LIMITS[key]) {
    blocking.push(`${key}: ${text.length} chars exceeds the limit of ${LIMITS[key]}`);
  }
  if (key === 'reddit') {
    const title = String(p.title || '').trim();
    if (!title) blocking.push('reddit: empty title');
    else if (title.length > Number(cfg.reddit_title_max_chars)) {
      blocking.push(`reddit: title is ${title.length} chars, limit ${cfg.reddit_title_max_chars}`);
    }
  }

  // Links: every URL must be the source URL. Anything else may be invented by the model.
  const urls = (text.match(URL_RE) || []).map(normUrl);
  const foreign = urls.filter((u) => u !== allowed);
  if (foreign.length) blocking.push(`${key}: contains link(s) that are not the source: ${foreign.join(', ')}`);
  if (allowed && !urls.includes(allowed)) warnings.push(`${key}: source link is missing`);

  // Numbers and quantified claims cannot be checked against the article here, so a human must.
  const claims = [...new Set(text.match(CLAIM_RE) || [])];
  if (claims.length) warnings.push(`${key}: numeric claims to verify manually: ${claims.join(', ')}`);

  if (key === 'twitter' && (text.match(/#\w+/g) || []).length > 3) warnings.push('twitter: more than 3 hashtags');
}

const lines = [];
lines.push(blocking.length ? `⛔ BLOCKING (${blocking.length}) - publishing is disabled:\n- ${blocking.join('\n- ')}` : '✅ No blocking errors');
lines.push(warnings.length ? `⚠️ Warnings (${warnings.length}):\n- ${warnings.join('\n- ')}` : '✅ No warnings');

return [{
  json: {
    ...agent,
    output: posts,
    blocking_errors: blocking,
    blocking_count: blocking.length,
    warnings,
    warnings_count: warnings.length,
    quality_summary: lines.join('\n\n'),
  },
}];

// Runs after all four publishers finished (Merge). Reads each publisher by name, so order does not matter.
const cfg = $('Config').first().json;
const PUBLISHERS = [
  ['X (Twitter)', 'Upload Post X'],
  ['Threads', 'Upload Post Threads'],
  ['LinkedIn', 'Upload Post Linkedin'],
  ['Reddit', 'Upload Post Reddit'],
];
const published = [];
const errors = [];

for (const [label, nodeName] of PUBLISHERS) {
  let first = null;
  try { first = $(nodeName).first(); } catch (e) { first = null; }
  if (!first) { errors.push(`${label}: node did not run`); continue; }
  const err = first.json && first.json.error;
  if (err) errors.push(`${label}: ${String(err.message || err).slice(0, 200)}`);
  else published.push(label);
}

const quality = $('Quality Checks').first().json;
const decision = $('Wait to approve by user').first().json.decision;
const status = errors.length === 0 ? 'published' : (published.length === 0 ? 'failed' : 'partial');

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow: 'social_posts_autopublisher',
    run_status: status,
    source_url: cfg.workflow_url,
    decision,
    blocking_errors: quality.blocking_errors.join(' | '),
    warnings: quality.warnings.join(' | '),
    platforms_published: published.join(', '),
    platform_errors: errors.join(' | '),
    estimated_cost_usd: cfg.estimated_cost_usd,
    execution_id: $execution.id,
  },
}];

